define(['jquery'], function($) {

    /**
     * Inicializa los componentes interactivos del dashboard.
     */
    var init = function() {
        registerEventListeners();
        setupTabNavigation();
    };

    /**
     * Registra los listeners de eventos para los elementos interactivos.
     */
    var registerEventListeners = function() {
        // Hover para tarjetas de estadísticas con efecto de elevación
        $('.stat-card').hover(
            function() {
                $(this).css('transform', 'translateY(-5px)');
            },
            function() {
                $(this).css('transform', 'translateY(0)');
            }
        );
        
        // Botón para actualizar datos
        $('#refresh-data').on('click', function() {
            location.reload();
        });
    };

    /**
     * Configura la navegación por pestañas y subpestañas.
     */
    var setupTabNavigation = function() {
        // Gestión de pestañas principales
        $('.nav-tabs .nav-link').on('click', function(e) {
            e.preventDefault();
            var target = $(this).attr('href');
            
            // Ocultar todos los paneles
            $('.tab-pane').removeClass('show active');
            
            // Mostrar el panel seleccionado
            $(target).addClass('show active');
            
            // Actualizar las clases de pestañas activas
            $('.nav-tabs .nav-link').removeClass('active');
            $(this).addClass('active');
        });
        
        // Gestión de subpestañas (si existen)
        $('.subtabs .nav-link').on('click', function(e) {
            e.preventDefault();
            var target = $(this).attr('href');
            
            // Ocultar todos los subpaneles
            $('.subtab-pane').removeClass('show active');
            
            // Mostrar el subpanel seleccionado
            $(target).addClass('show active');
            
            // Actualizar las clases de subpestañas activas
            $('.subtabs .nav-link').removeClass('active');
            $(this).addClass('active');
        });
        
        // Alternancia entre vista de tabla y gráfico (si existe)
        $('#btn-table-view').on('click', function() {
            $('#table-view').show();
            $('#chart-view').hide();
            $(this).addClass('active');
            $('#btn-chart-view').removeClass('active');
        });
        
        $('#btn-chart-view').on('click', function() {
            $('#table-view').hide();
            $('#chart-view').show();
            $(this).addClass('active');
            $('#btn-table-view').removeClass('active');
        });
    };

    return {
        init: init
    };
});